/*
 * A088520  Permutation of natural numbers generated by 3-rowed array shown
 *          below.
 * https://oeis.org/A088520
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is obtained by reading the 3‑row array formed by filling
 *            columns with consecutive natural numbers and then listing the
 *            anti‑diagonals (from left to right). The algorithm below
 *            computes a(n) in O(1) time
 * Range:     u8 n <= 72, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /*  n ≥ 1  (inputs smaller than 1 are undefined)  */
    if (n == 1)
        return (seq_t)1;          /* first element (row 1, col 1) */

    /* Determine the diagonal d that contains n.
       For n = 2,3   → d = 2
       For n ≥ 4    → d = 3 + (n‑4)/3   (integer division) */
    idx_t d;
    if (n <= 3)
        d = 2;
    else
        d = 3 + (n - 4) / 3;

    /* Cumulative number of elements up to the previous diagonal
       SPrev = |{ all positions of diagonals < d }| */
    idx_t SPrev;
    if (d == 1)
        SPrev = 0;
    else if (d == 2)
        SPrev = 1;                 /* one element in diagonal 1   */
    else
        SPrev = 3 * (d - 1) - 3;   /* 3 elements per diagonal for d‑1 ≥ 2 */

    /* 0‑based offset of the desired element within diagonal d */
    idx_t offset = n - SPrev - 1;   /* 0 ≤ offset ≤ 2 */

    /* Row index (1‑based) within the diagonal */
    idx_t r = offset + 1;           /* r = 1,2, or 3 */
    /* Corresponding column index */
    idx_t c = d - r + 1;            /* c ≥ 1 */

    /* Value at position (r,c).
       For column c:

           if c is odd:
               r=1 → 3c-2
               r=2 → 3c-1
               r=3 → 3c
           if c is even:
               r=1 → 3c-1
               r=2 → 3c-2
               r=3 → 3c      */

    seq_t val;
    if ((c & 1) == 0) {            /* even column */
        if (r == 1)
            val = (seq_t)3 * (seq_t)c - 1;
        else if (r == 2)
            val = (seq_t)3 * (seq_t)c - 2;
        else /* r == 3 */
            val = (seq_t)3 * (seq_t)c;
    } else {                       /* odd column */
        if (r == 1)
            val = (seq_t)3 * (seq_t)c - 2;
        else if (r == 2)
            val = (seq_t)3 * (seq_t)c - 1;
        else /* r == 3 */
            val = (seq_t)3 * (seq_t)c;
    }

    return val;
}
